#[derive(Clone)]
struct OverworldDirectionArt {
    standing: SpriteFrame,
    walking: Option<SpriteFrame>,
}

impl OverworldDirectionArt {
    fn frame(&self, walking: bool) -> SpriteFrame {
        if walking {
            if let Some(frame) = &self.walking {
                return frame.clone();
            }
        }
        self.standing.clone()
    }
}

