fn apply_visible_happiness_service(
    runtime_shell: &mut BevyRuntimeShell,
    routine: RuntimeHappinessServiceRoutine,
) -> Result<()> {
    let snapshot = runtime_shell.shell.snapshot()?;
    let party_index = selected_party_index(runtime_shell)?;
    let mut rng = Random::new(snapshot.progression.rng_seed);
    let rng_roll = rng.randrange(256) as u8;
    let rng_seed_after = rng.seed();
    record_visible_runtime_action(
        runtime_shell,
        format!("special:happiness:{routine:?}:{party_index}:{rng_roll}"),
    )?;
    let used = runtime_shell.shell.apply_happiness_service(
        routine,
        party_index,
        rng_roll,
        rng_seed_after,
    )?;
    runtime_shell.last_audio_events.push(format!(
        "happiness routine={:?} party_index={} roll={} rng={} outcome={:?} checksum={:?}",
        routine, party_index, rng_roll, rng_seed_after, used.outcome.effect, used.state_checksum
    ));
    activate_visible_special_boundary_if_needed(runtime_shell, &used.outcome.effect)?;
    Ok(())
}

