    entries.extend(
        windowed_index_range(cursor_index, shop.inventory.len()).map(|index| {
            let item = &shop.inventory[index];
            let marker = if index == cursor_index { ">" } else { " " };
            compact_scene_label(
                &format!("{marker}{}", shop_buy_item_label(snapshot, item)),
                SCENE_DIALOG_TEXT_CHARS,
            )
        }),
    );
