fn audio_status_label(runtime_shell: &BevyRuntimeShell) -> Option<String> {
    if let Some(music) = &runtime_shell.active_music {
        let mut label = format!("MUSIC {}", compact_scene_label(music, 22));
        if !runtime_shell.pending_audio.is_empty() {
            label.push_str(&format!(" +{}", runtime_shell.pending_audio.len()));
        }
        return Some(label);
    }
    if let Some(music) = &runtime_shell.faded_music {
        return Some(format!("FADE {}", compact_scene_label(music, 24)));
    }
    if runtime_shell.pending_music_stop {
        return Some("MUSIC STOP".to_string());
    }
    None
}

fn visible_field_command_entries(
    snapshot: &RuntimeShellSnapshot,
    runtime_shell: &BevyRuntimeShell,
) -> Result<Vec<String>> {
    if runtime_shell.start_menu_cursor.is_some() {
        return visible_start_menu_entries(runtime_shell);
    }
    if visible_field_pack_is_open(runtime_shell) {
        return Ok(visible_field_pack_entries(snapshot, runtime_shell));
    }
    if runtime_shell.party_menu_open {
        return Ok(visible_party_menu_entries(snapshot, runtime_shell));
    }
    if runtime_shell.pokedex_menu_open {
        return Ok(visible_pokedex_menu_entries(snapshot, runtime_shell));
    }
    if runtime_shell.pokegear_menu_open {
        return Ok(visible_pokegear_menu_entries(snapshot, runtime_shell));
    }
    if runtime_shell.trainer_card_open {
        return Ok(visible_trainer_card_entries(snapshot));
    }
    if runtime_shell.options_menu_open {
        return Ok(visible_options_menu_entries(snapshot, runtime_shell));
    }
    if runtime_shell.save_menu_open {
        return Ok(Vec::new());
    }
    if runtime_shell.special_boundary.is_some() {
        return Ok(visible_special_boundary_entries(runtime_shell));
    }
    visible_field_idle_entries(snapshot, runtime_shell)
}

fn visible_field_idle_entries(
    snapshot: &RuntimeShellSnapshot,
    runtime_shell: &BevyRuntimeShell,
) -> Result<Vec<String>> {
    if !runtime_debug_overlays_enabled() {
        return Ok(Vec::new());
    }
    let mut entries = Vec::new();
    if let Some(map) = snapshot
        .maps
        .iter()
        .find(|map| map.map_name == snapshot.overworld.map_name)
    {
        let TilePosition {
            x: front_x,
            y: front_y,
        } = facing_runtime_tile(snapshot)?;
        if let Some(prompt) =
            field_prompt_label_checked(runtime_shell, snapshot, map, front_x, front_y)?
        {
            entries.push(compact_scene_label(&prompt, 30));
        } else {
            entries.push(compact_scene_label(
                &format!(
                    "{} ({}, {}) {:?}",
                    snapshot.overworld.map_name,
                    snapshot.overworld.tile.x,
                    snapshot.overworld.tile.y,
                    snapshot.overworld.facing
                ),
                30,
            ));
        }
    } else {
        entries.push(compact_scene_label(
            &format!("MISSING MAP {}", snapshot.overworld.map_name),
            30,
        ));
    }
    entries.push("START MENU".to_string());
    if snapshot.party.slots.is_empty() {
        entries.push("PARTY EMPTY".to_string());
    } else if let Some(lead) = snapshot.party.slots.first() {
        entries.push(compact_scene_label(
            &format!(
                "PARTY {} L{} {}/{}",
                lead.pokemon.species.id, lead.pokemon.level, lead.pokemon.hp, lead.pokemon.max_hp
            ),
            30,
        ));
    }
    let carried_items = carried_item_count(&snapshot.bag.items)
        + carried_item_count(&snapshot.bag.balls)
        + carried_item_count(&snapshot.bag.key_items)
        + snapshot.bag.tm_hm.len();
    entries.push(format!("PACK {carried_items}"));
    if let Some(registered) = snapshot.progression.registered_key_item.as_deref() {
        entries.push(compact_scene_label(&format!("SELECT {registered}"), 30));
    }
    if runtime_shell.quick_save_path.is_some() {
        entries.push("SAVE READY".to_string());
    }
    entries.truncate(SCENE_MENU_VISIBLE_ROWS);
    Ok(entries)
}

fn visible_start_menu_entries(runtime_shell: &BevyRuntimeShell) -> Result<Vec<String>> {
    let snapshot = runtime_shell.shell.snapshot()?;
    let options = visible_start_menu_options(runtime_shell, &snapshot);
    let selected = strict_readonly_cursor_index(
        &runtime_shell.start_menu_cursor,
        START_MENU_SURFACE_ID,
        options.len(),
    )
    .context("start menu is open without a valid cursor")?;
    Ok(options
        .iter()
        .enumerate()
        .map(|(index, option)| {
            let marker = if index == selected { ">" } else { " " };
            format!(
                "{marker}{}",
                start_menu_option_display_label(*option, &snapshot)
            )
        })
        .collect())
}

fn visible_field_pack_entries(
    snapshot: &RuntimeShellSnapshot,
    runtime_shell: &BevyRuntimeShell,
) -> Vec<String> {
    if let Some(mode) = runtime_shell.field_pack_target_mode {
        return visible_field_pack_target_entries(snapshot, runtime_shell, mode);
    }
    let active = active_visible_field_pack_pocket(runtime_shell);
    if runtime_shell.field_pack_action_cursor.is_some() {
        return visible_field_pack_action_entries(snapshot, runtime_shell, &active)
            .into_iter()
            .take(SCENE_MENU_VISIBLE_ROWS)
            .collect();
    }
    let mut entries = vec![format!(
        "POCKET: {}",
        field_pack_pocket_label(&active).to_uppercase()
    )];
    entries.extend(match active {
        FieldPackPocket::Items => selected_pack_entries(
            snapshot,
            &snapshot.bag.items,
            &runtime_shell.bag_cursor,
            "bag:items",
        ),
        FieldPackPocket::Balls => selected_pack_entries(
            snapshot,
            &snapshot.bag.balls,
            &runtime_shell.ball_cursor,
            "bag:balls",
        ),
        FieldPackPocket::KeyItems => selected_pack_entries(
            snapshot,
            &snapshot.bag.key_items,
            &runtime_shell.key_item_cursor,
            "bag:key-items",
        ),
        FieldPackPocket::TmHm => selected_tmhm_pack_entries(snapshot, runtime_shell),
        FieldPackPocket::Custom(pocket_id) => {
            let Some(items) = snapshot.bag.custom_pockets.get(&pocket_id) else {
                return vec![compact_scene_label(
                    &format!("INVALID POCKET {pocket_id}"),
                    30,
                )];
            };
            selected_pack_entries(
                snapshot,
                items,
                &runtime_shell.custom_item_cursor,
                &custom_pack_surface_id(&pocket_id),
            )
        }
    });
    entries.into_iter().take(SCENE_MENU_VISIBLE_ROWS).collect()
}

fn visible_field_pack_action_entries(
    snapshot: &RuntimeShellSnapshot,
    runtime_shell: &BevyRuntimeShell,
    pocket: &FieldPackPocket,
) -> Vec<String> {
    let actions = visible_field_pack_actions(pocket);
    let Some(selected) = strict_readonly_cursor_index(
        &runtime_shell.field_pack_action_cursor,
        "pack:actions",
        actions.len(),
    ) else {
        return vec![compact_scene_label("INVALID CURSOR pack:actions", 30)];
    };
    let mut entries = selected_field_pack_item_label(snapshot, runtime_shell, pocket)
        .map(|label| vec![compact_scene_label(&format!("ACTION {label}"), 30)])
        .unwrap_or_else(|| vec![compact_scene_label("INVALID CURSOR field:item", 30)]);
    entries.extend(actions.iter().enumerate().map(|(index, action)| {
        let marker = if index == selected { ">" } else { " " };
        format!("{marker}{}", visible_field_pack_action_label(*action))
    }));
    entries
}

fn visible_field_pack_target_entries(
    snapshot: &RuntimeShellSnapshot,
    runtime_shell: &BevyRuntimeShell,
    mode: FieldPackTargetMode,
) -> Vec<String> {
    let selected_party = runtime_shell
        .party_cursor
        .min(snapshot.party.slots.len().saturating_sub(1));
    let mut entries = selected_field_pack_item_label(
        snapshot,
        runtime_shell,
        &active_visible_field_pack_pocket(runtime_shell),
    )
    .map(|label| vec![compact_scene_label(&format!("ITEM {label}"), 30)])
    .unwrap_or_else(|| vec![compact_scene_label("INVALID CURSOR field:item", 30)]);
    if mode == FieldPackTargetMode::PartyMove {
        let Some(slot) = snapshot.party.slots.get(selected_party) else {
            return vec![compact_scene_label(
                &format!("INVALID PARTY SLOT {selected_party}"),
                30,
            )];
        };
        entries.push(party_slot_entry(slot, true));
        let selected_move = strict_readonly_cursor_index(
            &runtime_shell.party_move_cursor,
            &party_move_cursor_surface_id(slot.index),
            slot.pokemon.moves.len(),
        );
        let Some(selected_move) = selected_move else {
            entries.push(compact_scene_label(
                &format!("INVALID CURSOR party:{}:moves", slot.index),
                30,
            ));
            return entries.into_iter().take(SCENE_MENU_VISIBLE_ROWS).collect();
        };
        entries.extend(windowed_move_entries(
            snapshot,
            &slot.pokemon.moves,
            selected_move,
        ));
        return entries.into_iter().take(SCENE_MENU_VISIBLE_ROWS).collect();
    }
    entries.extend(windowed_party_slot_entries(snapshot, selected_party));
    if mode == FieldPackTargetMode::TmHmPokemon {
        if let Some(slot) = snapshot.party.slots.get(selected_party) {
            if slot.pokemon.moves.len() >= 4 {
                let selected_move = strict_readonly_cursor_index(
                    &runtime_shell.party_move_cursor,
                    &party_move_cursor_surface_id(slot.index),
                    slot.pokemon.moves.len(),
                );
                if let Some(selected_move) = selected_move {
                    entries.push(compact_scene_label("REPLACE MOVE", 30));
                    entries.extend(windowed_move_entries(
                        snapshot,
                        &slot.pokemon.moves,
                        selected_move,
                    ));
                } else {
                    entries.push(compact_scene_label(
                        &format!("INVALID CURSOR party:{}:moves", slot.index),
                        30,
                    ));
                }
            }
        }
    }
    entries.into_iter().take(SCENE_MENU_VISIBLE_ROWS).collect()
}

fn visible_party_menu_entries(
    snapshot: &RuntimeShellSnapshot,
    runtime_shell: &BevyRuntimeShell,
) -> Vec<String> {
    let selected_party_slot = runtime_shell
        .party_cursor
        .min(snapshot.party.slots.len().saturating_sub(1));
    if let Some(switch_cursor) = &runtime_shell.party_switch_cursor {
        let Some(source_slot) = snapshot.party.slots.get(selected_party_slot) else {
            return vec![compact_scene_label(
                &format!("INVALID PARTY SLOT {selected_party_slot}"),
                30,
            )];
        };
        let selected_target = strict_readonly_cursor_index(
            &Some(switch_cursor.clone()),
            &party_switch_cursor_surface_id(source_slot.index),
            snapshot.party.slots.len(),
        );
        let Some(selected_target) = selected_target else {
            return vec![compact_scene_label("INVALID CURSOR party:switch", 30)];
        };
        return windowed_index_range(selected_target, snapshot.party.slots.len())
            .map(|index| {
                let slot = &snapshot.party.slots[index];
                party_switch_slot_entry(
                    slot,
                    index == selected_target,
                    index == selected_party_slot,
                )
            })
            .collect();
    }
    if runtime_shell.party_summary_open {
        return visible_party_summary_entries(snapshot, runtime_shell);
    }
    if let Some(action_cursor) = &runtime_shell.party_action_cursor {
        let actions = match visible_party_actions(snapshot, runtime_shell) {
            Ok(actions) => actions,
            Err(error) => {
                return vec![compact_scene_label(
                    &format!("INVALID PARTY ACTIONS {error:#}"),
                    30,
                )];
            }
        };
        let selected_action = strict_readonly_cursor_index(
            &Some(action_cursor.clone()),
            "party:actions",
            actions.len(),
        );
        let Some(selected_action) = selected_action else {
            return vec![compact_scene_label("INVALID CURSOR party:actions", 30)];
        };
        let row_count = normal_visible_party_menu_row_count(snapshot);
        let selected_row = runtime_shell.party_cursor.min(row_count.saturating_sub(1));
        let mut entries = windowed_index_range(selected_row, row_count)
            .map(|index| {
                if index >= snapshot.party.slots.len() {
                    party_cancel_entry(index == selected_row)
                } else {
                    let slot = &snapshot.party.slots[index];
                    party_slot_entry(slot, index == selected_row)
                }
            })
            .collect::<Vec<_>>();
        entries.push("SUBMENU:".to_string());
        entries.extend(
            windowed_index_range(selected_action, actions.len()).map(|index| {
                let action = actions[index];
                let marker = if index == selected_action { ">" } else { " " };
                party_submenu_action_entry(action, marker)
            }),
        );
        return entries.into_iter().take(SCENE_MENU_VISIBLE_ROWS).collect();
    }
    if runtime_shell.fly_cursor.is_some() {
        return visible_fly_destination_entries(snapshot, runtime_shell);
    }
    let row_count = normal_visible_party_menu_row_count(snapshot);
    let selected_row = runtime_shell.party_cursor.min(row_count.saturating_sub(1));
    windowed_index_range(selected_row, row_count)
        .map(|index| {
            if index >= snapshot.party.slots.len() {
                party_cancel_entry(index == selected_row)
            } else {
                let slot = &snapshot.party.slots[index];
                party_slot_entry(slot, index == selected_row)
            }
        })
        .collect()
}

fn visible_party_summary_entries(
    snapshot: &RuntimeShellSnapshot,
    runtime_shell: &BevyRuntimeShell,
) -> Vec<String> {
    let selected = runtime_shell
        .party_cursor
        .min(snapshot.party.slots.len().saturating_sub(1));
    let Some(slot) = snapshot.party.slots.get(selected) else {
        return Vec::new();
    };
    let pokemon = &slot.pokemon;
    let status = pokemon
        .status
        .as_deref()
        .filter(|status| !status.is_empty())
        .unwrap_or(if pokemon.hp == 0 { "FNT" } else { "OK" });
    let held = pokemon.item.as_deref().unwrap_or("-");
    let mut entries = vec![
        compact_scene_label(
            &format!(
                "SUMMARY {}/{} {}",
                selected + 1,
                snapshot.party.slots.len(),
                pokemon.nickname
            ),
            30,
        ),
        compact_scene_label(
            &format!(
                "{} L{} HP {}/{} {status}",
                pokemon.species.id, pokemon.level, pokemon.hp, pokemon.max_hp
            ),
            30,
        ),
        compact_scene_label(
            &format!(
                "ATK {} DEF {} SPD {}",
                pokemon.attack, pokemon.defense, pokemon.speed
            ),
            30,
        ),
        compact_scene_label(
            &format!(
                "SAT {} SDF {} ITEM {held}",
                pokemon.special_attack, pokemon.special_defense
            ),
            30,
        ),
        compact_scene_label(
            &format!(
                "EXP {} HAP {} OT {}#{}",
                pokemon.experience,
                pokemon.happiness,
                pokemon.original_trainer_name,
                pokemon.original_trainer_id
            ),
            30,
        ),
    ];
    if pokemon.moves.is_empty() {
        entries.push("NO MOVES".to_string());
    } else {
        entries.extend(
            pokemon
                .moves
                .iter()
                .take(SCENE_MENU_VISIBLE_ROWS.saturating_sub(entries.len()))
                .map(|learned| move_menu_entry(snapshot, learned, " ")),
        );
    }
    entries.into_iter().take(SCENE_MENU_VISIBLE_ROWS).collect()
}

fn visible_fly_destination_entries(
    snapshot: &RuntimeShellSnapshot,
    runtime_shell: &BevyRuntimeShell,
) -> Vec<String> {
    let destinations = active_fly_destinations(snapshot, &runtime_shell.shell);
    let selected = strict_readonly_cursor_index(
        &runtime_shell.fly_cursor,
        "fly:destinations",
        destinations.len(),
    );
    let Some(selected) = selected else {
        return vec![compact_scene_label("INVALID CURSOR fly:destinations", 30)];
    };
    destinations
        .iter()
        .enumerate()
        .skip(visible_window_start(
            selected,
            destinations.len(),
            SCENE_MENU_VISIBLE_ROWS,
        ))
        .take(SCENE_MENU_VISIBLE_ROWS)
        .map(|(index, destination)| {
            let marker = if index == selected { ">" } else { " " };
            let label = fly_destination_label(destination);
            compact_scene_label(&format!("{marker}{label}"), SCENE_DIALOG_TEXT_CHARS)
        })
        .collect()
}

fn visible_pokedex_menu_entries(
    snapshot: &RuntimeShellSnapshot,
    runtime_shell: &BevyRuntimeShell,
) -> Vec<String> {
    if snapshot.pokemon.is_empty() {
        return Vec::new();
    }
    if runtime_shell.pokedex_detail_open {
        return visible_pokedex_detail_entries(snapshot, runtime_shell);
    }
    let selected = runtime_shell
        .pokedex_cursor
        .min(snapshot.pokemon.len().saturating_sub(1));
    windowed_index_range(selected, snapshot.pokemon.len())
        .map(|index| {
            let species = &snapshot.pokemon[index];
            let marker = if index == selected { ">" } else { " " };
            pokedex_entry_row(snapshot, species, marker)
        })
        .collect()
}

fn visible_pokedex_detail_entries(
    snapshot: &RuntimeShellSnapshot,
    runtime_shell: &BevyRuntimeShell,
) -> Vec<String> {
    let Ok(species) = selected_pokedex_catalog_species(snapshot, runtime_shell.pokedex_cursor)
    else {
        return vec![compact_scene_label("INVALID POKEDEX", 30)];
    };
    let Some(entry) = snapshot
        .presentation
        .pokedex_entries
        .get(&species.species_id)
    else {
        return vec![compact_scene_label(
            &format!("INVALID DEX {}", species.species_id),
            30,
        )];
    };
    let mut entries = vec![
        compact_scene_label(
            &format!(
                "#{:03} {} {}",
                species.int_id, species.species_id, entry.classification
            ),
            30,
        ),
        compact_scene_label(
            &format!(
                "HT {} WT {} TYPE {}/{}",
                entry.height_digits, entry.weight_digits, species.type1, species.type2
            ),
            30,
        ),
        compact_scene_label(
            &format!(
                "CATCH {} EXP {} GROW {}",
                species.catch_rate, species.base_exp, species.growth_rate
            ),
            30,
        ),
        compact_scene_label(
            &format!(
                "EGG {}/{} AB {}",
                species.egg_group1, species.egg_group2, species.ability
            ),
            30,
        ),
    ];
    entries.extend(
        entry
            .pages
            .iter()
            .flat_map(|page| wrap_scene_dialog_line(page, SCENE_DIALOG_TEXT_CHARS))
            .take(SCENE_MENU_VISIBLE_ROWS.saturating_sub(entries.len())),
    );
    entries.into_iter().take(SCENE_MENU_VISIBLE_ROWS).collect()
}

fn visible_pokegear_menu_entries(
    snapshot: &RuntimeShellSnapshot,
    runtime_shell: &BevyRuntimeShell,
) -> Vec<String> {
    if runtime_shell.pokegear_page == PokegearPage::Phone {
        return visible_pokegear_phone_entries(snapshot, runtime_shell);
    }
    let landmarks = &snapshot.presentation.pokegear_landmarks.landmarks;
    if landmarks.is_empty() {
        return Vec::new();
    }
    if runtime_shell.pokegear_detail_open {
        return visible_pokegear_detail_entries(snapshot, runtime_shell);
    }
    let selected = runtime_shell
        .pokegear_cursor
        .min(landmarks.len().saturating_sub(1));
    windowed_index_range(selected, landmarks.len())
        .map(|index| {
            let landmark = &landmarks[index];
            let marker = if index == selected { ">" } else { " " };
            pokegear_landmark_row(snapshot, landmark, marker)
        })
        .collect()
}

fn visible_pokegear_phone_entries(
    snapshot: &RuntimeShellSnapshot,
    runtime_shell: &BevyRuntimeShell,
) -> Vec<String> {
    let contact_ids = visible_pokegear_phone_contact_ids(snapshot);
    if contact_ids.is_empty() {
        return vec!["PHONE EMPTY".to_string()];
    }
    if runtime_shell.pokegear_detail_open {
        return visible_pokegear_phone_detail_entries(snapshot, runtime_shell);
    }
    let selected = runtime_shell
        .pokegear_phone_cursor
        .min(contact_ids.len().saturating_sub(1));
    let mut entries = Vec::new();
    entries.extend(
        windowed_index_range(selected, contact_ids.len()).map(|index| {
            let contact_id = &contact_ids[index];
            let marker = if index == selected { ">" } else { " " };
            let label = snapshot
                .special
                .phone_contacts
                .0
                .get(contact_id)
                .map(|contact| contact.primary_label.as_str())
                .unwrap_or(contact_id.as_str());
            compact_scene_label(&format!("{marker}{label}"), SCENE_DIALOG_TEXT_CHARS)
        }),
    );
    entries.into_iter().take(SCENE_MENU_VISIBLE_ROWS).collect()
}

fn visible_pokegear_phone_detail_entries(
    snapshot: &RuntimeShellSnapshot,
    runtime_shell: &BevyRuntimeShell,
) -> Vec<String> {
    let Ok(contact_id) = selected_visible_pokegear_phone_contact_id(snapshot, runtime_shell) else {
        return Vec::new();
    };
    let Some(contact) = snapshot.special.phone_contacts.0.get(&contact_id) else {
        return vec![compact_scene_label(
            &format!("INVALID CONTACT {contact_id}"),
            30,
        )];
    };
    let mut entries = vec![compact_scene_label(
        &format!(">{}", contact.primary_label),
        30,
    )];
    if runtime_debug_overlays_enabled() {
        entries.push(compact_scene_label(&format!("ID {contact_id}"), 30));
        entries.push(compact_scene_label(
            &format!("MAP {}", contact.map_constant.as_deref().unwrap_or("-")),
            30,
        ));
        entries.push(compact_scene_label(
            &format!("CALLEE {}", contact.callee_script.as_deref().unwrap_or("-")),
            30,
        ));
    } else if let Some(map_constant) = contact.map_constant.as_deref() {
        entries.push(compact_scene_label(map_constant, 30));
    }
    if contact.callee_script.is_some() {
        entries.push("CALL".to_string());
    } else if runtime_debug_overlays_enabled() {
        entries.push(compact_scene_label(
            &format!("CALLER {}", contact.caller_script.as_deref().unwrap_or("-")),
            30,
        ));
    }
    entries.into_iter().take(SCENE_MENU_VISIBLE_ROWS).collect()
}

fn visible_pokegear_phone_contact_ids(snapshot: &RuntimeShellSnapshot) -> Vec<String> {
    snapshot
        .script_events
        .phone_numbers
        .iter()
        .cloned()
        .collect()
}

fn selected_visible_pokegear_phone_contact_id(
    snapshot: &RuntimeShellSnapshot,
    runtime_shell: &BevyRuntimeShell,
) -> Result<String> {
    let contact_ids = visible_pokegear_phone_contact_ids(snapshot);
    if contact_ids.is_empty() {
        anyhow::bail!("Pokegear has no registered phone contacts");
    }
    contact_ids
        .get(runtime_shell.pokegear_phone_cursor)
        .cloned()
        .with_context(|| {
            format!(
                "Pokegear phone cursor {} is out of range for {} contacts",
                runtime_shell.pokegear_phone_cursor,
                contact_ids.len()
            )
        })
}

fn visible_pokegear_detail_entries(
    snapshot: &RuntimeShellSnapshot,
    runtime_shell: &BevyRuntimeShell,
) -> Vec<String> {
    let Ok(landmark) = selected_pokegear_landmark(snapshot, runtime_shell.pokegear_cursor) else {
        return Vec::new();
    };
    if !runtime_debug_overlays_enabled() {
        return vec![
            compact_scene_label(&format!(">{}", landmark.name), 30),
            compact_scene_label(&format!("REGION {}", landmark.region), 30),
            compact_scene_label(&format!("{},{}", landmark.x, landmark.y), 30),
        ];
    }
    let current_landmark = snapshot
        .presentation
        .pokegear_landmarks
        .map_to_landmark
        .get(&snapshot.overworld.map_name)
        .map(|constant| constant.as_str())
        .unwrap_or("-");
    let maps = snapshot
        .presentation
        .pokegear_landmarks
        .map_to_landmark
        .iter()
        .filter(|(_, constant)| *constant == &landmark.constant)
        .map(|(map_name, _)| map_name.as_str())
        .collect::<Vec<_>>();
    vec![
        compact_scene_label(&format!("{} {}", landmark.constant, landmark.name), 30),
        compact_scene_label(&format!("ID {} LABEL {}", landmark.id, landmark.label), 30),
        compact_scene_label(
            &format!(
                "POS {},{} REGION {}",
                landmark.x, landmark.y, landmark.region
            ),
            30,
        ),
        compact_scene_label(&format!("CURRENT {current_landmark}"), 30),
        compact_scene_label(&format!("MAPS {}", maps.len()), 30),
        compact_scene_label(&maps.join(" / "), 30),
    ]
}

fn visible_options_menu_entries(
    snapshot: &RuntimeShellSnapshot,
    runtime_shell: &BevyRuntimeShell,
) -> Vec<String> {
    let selected = runtime_shell
        .options_cursor
        .min(OPTIONS_MENU_ITEMS.len().saturating_sub(1));
    windowed_index_range(selected, OPTIONS_MENU_ITEMS.len())
        .map(|index| {
            let item = OPTIONS_MENU_ITEMS[index];
            let marker = if index == selected { ">" } else { " " };
            let value = option_value_for_item(&snapshot.trainer.options, item);
            if value.is_empty() {
                format!("{marker}{}", options_menu_item_label(item))
            } else {
                format!("{marker}{}: {value}", options_menu_item_label(item))
            }
        })
        .collect()
}

fn visible_trainer_card_entries(snapshot: &RuntimeShellSnapshot) -> Vec<String> {
    vec![
        compact_scene_label(&format!("NAME/ {}", snapshot.trainer.player_name), 30),
        format!("ID {:05}", snapshot.trainer.player_id),
        format!(
            "MONEY {}",
            format_trainer_card_money(snapshot.trainer.money)
        ),
        format!("#DEX {:>3}", snapshot.progression.pokedex_owned.min(999)),
        compact_scene_label(&format!("TIME {:?}", snapshot.progression.time), 30),
        format!(
            "BADGES {}",
            visible_badge_count(&snapshot.progression.badges)
        ),
    ]
}

fn visible_save_slot_preview_entries_for_path(
    runtime_shell: &BevyRuntimeShell,
    path: &std::path::Path,
) -> Vec<String> {
    match runtime_shell.shell.runtime().load_save_summary(path) {
        Ok(summary) => vec![
            compact_scene_label(
                &format!(
                    "EXISTS F{} {} {}",
                    summary.saved_frame(),
                    summary.modpack().id(),
                    summary.pack_content_hash()
                ),
                30,
            ),
            compact_scene_label(&format!("SAVE VERSION {}", summary.format_version()), 30),
            compact_scene_label(&format!("SAVE PACK {}", summary.modpack().id()), 30),
            compact_scene_label(
                &format!(
                    "SAVE HASH {} {}",
                    summary.modpack().hash(),
                    summary.pack_content_hash()
                ),
                30,
            ),
        ],
        Err(error) => vec![compact_scene_label(&format!("INVALID SAVE {error}"), 30)],
    }
}

fn visible_special_boundary_entries(runtime_shell: &BevyRuntimeShell) -> Vec<String> {
    let Some(boundary) = &runtime_shell.special_boundary else {
        return Vec::new();
    };
    visible_special_boundary_display_entries(boundary)
}

fn visible_special_boundary_display_entries(boundary: &SpecialBoundaryDisplay) -> Vec<String> {
    vec![format!(">{}", boundary.label)]
}

fn spawn_battle_battler_markers(
    commands: &mut Commands,
    snapshot: &RuntimeShellSnapshot,
    battle: &crate::RuntimeBattleSnapshot,
    rendered_art: &mut RenderedTilesetArt,
    asset_root: &AssetRoot,
    images: &mut Assets<Image>,
) -> Result<()> {
    spawn_battler_marker(
        commands,
        rendered_art,
        asset_root,
        images,
        &battle.enemy_pokemon.species.id,
        PokemonSpriteSide::Front,
        battle.enemy_pokemon.hp,
        battle.enemy_pokemon.max_hp,
        Vec3::new(
            PLAYFIELD_LEFT + TILE_SIZE * 15.0,
            PLAYFIELD_TOP - TILE_SIZE * 4.5,
            3.0,
        ),
        Vec2::new(TILE_SIZE * 2.2, TILE_SIZE * 1.8),
    )?;
    if let Some(active_index) = battle.active_player_party_index {
        if let Some(slot) = snapshot
            .party
            .slots
            .iter()
            .find(|slot| slot.index == active_index)
        {
            spawn_battler_marker(
                commands,
                rendered_art,
                asset_root,
                images,
                &slot.pokemon.species.id,
                PokemonSpriteSide::Back,
                slot.pokemon.hp,
                slot.pokemon.max_hp,
                Vec3::new(
                    PLAYFIELD_LEFT + TILE_SIZE * 5.0,
                    PLAYFIELD_TOP - TILE_SIZE * 12.5,
                    3.0,
                ),
                Vec2::new(TILE_SIZE * 2.4, TILE_SIZE * 1.9),
            )?;
        }
    }
    Ok(())
}

fn spawn_battler_marker(
    commands: &mut Commands,
    rendered_art: &mut RenderedTilesetArt,
    asset_root: &AssetRoot,
    images: &mut Assets<Image>,
    species_id: &str,
    side: PokemonSpriteSide,
    hp: u16,
    max_hp: u16,
    position: Vec3,
    base_size: Vec2,
) -> Result<()> {
    let fraction = hp_fraction(hp, max_hp);
    let size = Vec2::new(
        (base_size.x * (0.72 + fraction * 0.28)).max(TILE_SIZE * 0.65),
        (base_size.y * (0.72 + fraction * 0.28)).max(TILE_SIZE * 0.55),
    );
    let Some(frame) =
        pokemon_frame_for_art(rendered_art, asset_root, species_id, side, false, images)
    else {
        anyhow::bail!(
            "required battle Pokemon art {} {:?} could not be rendered: {}",
            species_id,
            side,
            pokemon_art_error(rendered_art, species_id, side, false)
        );
    };
    let faint = if fraction <= 0.0 { 0.42 } else { 1.0 };
    commands.spawn((
        SpriteBundle {
            texture: frame.handle,
            sprite: Sprite {
                color: Color::rgba(faint, faint, faint, 1.0),
                custom_size: Some(frame.size * 2.25),
                ..default()
            },
            transform: Transform::from_translation(position),
            ..default()
        },
        BattleBattlerMarker,
    ));
    commands.spawn((
        SpriteBundle {
            sprite: Sprite {
                color: Color::rgba(0.04, 0.05, 0.04, 0.64),
                custom_size: Some(Vec2::new(size.x * 1.12, TILE_SIZE * 0.22)),
                ..default()
            },
            transform: Transform::from_xyz(
                position.x,
                position.y - size.y * 0.58,
                position.z - 0.1,
            ),
            ..default()
        },
        BattleBattlerMarker,
    ));
    Ok(())
}

fn spawn_battle_hud(
    commands: &mut Commands,
    snapshot: &RuntimeShellSnapshot,
    battle: &crate::RuntimeBattleSnapshot,
    rendered_art: &mut RenderedTilesetArt,
    asset_root: &AssetRoot,
    images: &mut Assets<Image>,
) {
    spawn_battle_hud_side(
        commands,
        rendered_art,
        asset_root,
        images,
        &battle.enemy_pokemon,
        BattleHpSide::Enemy,
    );
    let Some(active_index) = battle.active_player_party_index else {
        return;
    };
    let Some(slot) = snapshot
        .party
        .slots
        .iter()
        .find(|slot| slot.index == active_index)
    else {
        return;
    };
    spawn_battle_hud_side(
        commands,
        rendered_art,
        asset_root,
        images,
        &slot.pokemon,
        BattleHpSide::Player,
    );
}

fn spawn_battle_hud_side(
    commands: &mut Commands,
    rendered_art: &mut RenderedTilesetArt,
    asset_root: &AssetRoot,
    images: &mut Assets<Image>,
    pokemon: &crate::core::models::pokemon::Pokemon,
    side: BattleHpSide,
) {
    let (name_tile_x, name_tile_y, level_tile_x, level_tile_y, hp_tile_x, hp_tile_y) = match side {
        BattleHpSide::Enemy => (1.0, 0.0, 6.0, 1.0, 2.0, 2.0),
        BattleHpSide::Player => (10.0, 7.0, 14.0, 8.0, 10.0, 9.0),
    };
    spawn_battle_hud_bitmap_text(
        commands,
        rendered_art,
        asset_root,
        images,
        &compact_scene_label(&pokemon.nickname, 10),
        name_tile_x,
        name_tile_y,
        3.7,
    );
    let level_or_status = battle_status_token(pokemon.status.as_deref())
        .map(str::to_string)
        .unwrap_or_else(|| format!("L{}", pokemon.level));
    spawn_battle_hud_bitmap_text(
        commands,
        rendered_art,
        asset_root,
        images,
        &level_or_status,
        level_tile_x,
        level_tile_y,
        3.7,
    );
    spawn_battle_hud_hp_bar(
        commands,
        rendered_art,
        asset_root,
        images,
        hp_tile_x,
        hp_tile_y,
        pokemon.hp,
        pokemon.max_hp,
        side,
    );
    if side == BattleHpSide::Player {
        spawn_battle_hud_bitmap_text(
            commands,
            rendered_art,
            asset_root,
            images,
            &format!("{:>3}/{:>3}", pokemon.hp.min(999), pokemon.max_hp.min(999)),
            hp_tile_x + 1.0,
            hp_tile_y + 1.0,
            3.7,
        );
    }
}

fn spawn_battle_hud_bitmap_text(
    commands: &mut Commands,
    rendered_art: &mut RenderedTilesetArt,
    asset_root: &AssetRoot,
    images: &mut Assets<Image>,
    text: &str,
    tile_x: f32,
    tile_y: f32,
    z: f32,
) {
    let (x, y) = battle_hud_tile_origin(tile_x, tile_y);
    for (index, frame) in bitmap_text_frames(rendered_art, asset_root, images, text)
        .into_iter()
        .enumerate()
    {
        commands.spawn((
            SpriteBundle {
                texture: frame.handle,
                sprite: Sprite {
                    custom_size: Some(frame.size),
                    ..default()
                },
                transform: Transform::from_xyz(x + index as f32 * BITMAP_FONT_ADVANCE, y, z),
                ..default()
            },
            BattleHudMarker,
            BattleCommandMarker,
        ));
    }
}

fn spawn_battle_hud_hp_bar(
    commands: &mut Commands,
    rendered_art: &mut RenderedTilesetArt,
    asset_root: &AssetRoot,
    images: &mut Assets<Image>,
    tile_x: f32,
    tile_y: f32,
    hp: u16,
    max_hp: u16,
    side: BattleHpSide,
) {
    spawn_battle_hud_bitmap_text(
        commands,
        rendered_art,
        asset_root,
        images,
        "HP",
        tile_x,
        tile_y,
        3.7,
    );
    let (label_x, label_y) = battle_hud_tile_origin(tile_x, tile_y);
    commands.spawn((
        SpriteBundle {
            sprite: Sprite {
                color: Color::rgba(0.04, 0.05, 0.04, 0.88),
                custom_size: Some(Vec2::new(TILE_SIZE * 8.9, TILE_SIZE * 0.34)),
                ..default()
            },
            transform: Transform::from_xyz(
                label_x + TILE_SIZE * 4.45,
                label_y - TILE_SIZE * 0.18,
                3.55,
            ),
            ..default()
        },
        BattleHudMarker,
        BattleCommandMarker,
    ));
    commands.spawn((
        SpriteBundle {
            sprite: Sprite {
                color: Color::rgba(0.74, 0.80, 0.66, 0.98),
                custom_size: Some(Vec2::new(TILE_SIZE * 0.92, TILE_SIZE * 0.22)),
                ..default()
            },
            transform: Transform::from_xyz(
                label_x + TILE_SIZE * 0.56,
                label_y - TILE_SIZE * 0.18,
                3.6,
            ),
            ..default()
        },
        BattleHudMarker,
        BattleCommandMarker,
    ));
    let fill_pixels = battle_hud_hp_pixels(hp, max_hp);
    let fill_width = (fill_pixels as f32 / SOURCE_TILE_SIZE as f32) * TILE_SIZE;
    let inner_start_x = label_x + TILE_SIZE * 2.0;
    let fill_y = label_y - TILE_SIZE * 0.18;
    commands.spawn((
        SpriteBundle {
            sprite: Sprite {
                color: Color::rgba(0.82, 0.86, 0.74, 0.96),
                custom_size: Some(Vec2::new(
                    TILE_SIZE * BATTLE_HUD_HP_BAR_LENGTH_TILES,
                    TILE_SIZE * 0.20,
                )),
                ..default()
            },
            transform: Transform::from_xyz(
                inner_start_x + TILE_SIZE * BATTLE_HUD_HP_BAR_LENGTH_TILES * 0.5,
                fill_y,
                3.61,
            ),
            ..default()
        },
        BattleHudMarker,
        BattleCommandMarker,
    ));
    if fill_pixels > 0 {
        commands.spawn((
            SpriteBundle {
                sprite: Sprite {
                    color: battle_hud_hp_color(fill_pixels),
                    custom_size: Some(Vec2::new(fill_width, TILE_SIZE * 0.20)),
                    ..default()
                },
                transform: Transform::from_xyz(inner_start_x + fill_width * 0.5, fill_y, 3.62),
                ..default()
            },
            BattleHudMarker,
            BattleCommandMarker,
        ));
    }
    let end_x = inner_start_x + TILE_SIZE * BATTLE_HUD_HP_BAR_LENGTH_TILES + TILE_SIZE * 0.18;
    commands.spawn((
        SpriteBundle {
            sprite: Sprite {
                color: if side == BattleHpSide::Player {
                    Color::rgba(0.74, 0.80, 0.66, 0.98)
                } else {
                    Color::rgba(0.66, 0.70, 0.60, 0.98)
                },
                custom_size: Some(Vec2::new(TILE_SIZE * 0.24, TILE_SIZE * 0.30)),
                ..default()
            },
            transform: Transform::from_xyz(end_x, fill_y, 3.62),
            ..default()
        },
        BattleHudMarker,
        BattleCommandMarker,
    ));
}

fn battle_hud_tile_origin(tile_x: f32, tile_y: f32) -> (f32, f32) {
    (
        PLAYFIELD_LEFT + tile_x * TILE_SIZE + (SOURCE_TILE_SIZE as f32 * BATTLE_HUD_SCALE * 0.5),
        PLAYFIELD_TOP - tile_y * TILE_SIZE - (SOURCE_TILE_SIZE as f32 * BATTLE_HUD_SCALE * 0.5),
    )
}

fn battle_hud_hp_pixels(hp: u16, max_hp: u16) -> u16 {
    if max_hp == 0 || hp == 0 {
        return 0;
    }
    let clamped_hp = hp.min(max_hp);
    let pixels = ((u32::from(clamped_hp) * u32::from(BATTLE_HUD_HP_BAR_LENGTH_PX))
        / u32::from(max_hp)) as u16;
    pixels.max(1).min(BATTLE_HUD_HP_BAR_LENGTH_PX)
}

fn battle_hud_hp_color(fill_pixels: u16) -> Color {
    if fill_pixels > BATTLE_HUD_HP_BAR_LENGTH_PX / 2 {
        Color::rgba(0.0, 0.74, 0.0, 0.96)
    } else if fill_pixels >= ((u32::from(BATTLE_HUD_HP_BAR_LENGTH_PX) * 21) / 100) as u16 {
        Color::rgba(0.98, 0.72, 0.0, 0.96)
    } else {
        Color::rgba(0.96, 0.0, 0.0, 0.96)
    }
}

fn battle_status_token(status: Option<&str>) -> Option<&'static str> {
    match status? {
        "POISON" => Some("PSN"),
        "SLEEP" => Some("SLP"),
        "PARALYSIS" => Some("PAR"),
        "BURN" => Some("BRN"),
        "FREEZE" => Some("FRZ"),
        _ => None,
    }
}

fn spawn_battle_command_menu(
    commands: &mut Commands,
    snapshot: &RuntimeShellSnapshot,
    runtime_shell: &BevyRuntimeShell,
    battle: &crate::RuntimeBattleSnapshot,
    rendered_art: &mut RenderedTilesetArt,
    asset_root: &AssetRoot,
    images: &mut Assets<Image>,
) {
    if runtime_shell.battle_move_cursor.is_some() {
        spawn_battle_move_menu(
            commands,
            snapshot,
            runtime_shell,
            battle,
            rendered_art,
            asset_root,
            images,
        );
        return;
    }
    let entries = visible_battle_command_menu_entries(snapshot, runtime_shell, battle);
    if entries.is_empty() {
        return;
    }
    if battle_command_entries_are_main_menu(&entries) {
        spawn_battle_main_command_menu(commands, rendered_art, asset_root, images, &entries);
        return;
    }
    spawn_battle_window(
        commands,
        rendered_art,
        asset_root,
        images,
        BATTLE_TEXT_BOX_LEFT_TILE,
        BATTLE_TEXT_BOX_TOP_TILE,
        BATTLE_TEXT_BOX_WIDTH_TILES,
        BATTLE_TEXT_BOX_HEIGHT_TILES,
        3.5,
    );
    let two_columns = scene_menu_uses_two_columns(&entries);
    for (index, entry) in entries.iter().enumerate() {
        let (tile_x, tile_y) = battle_submenu_entry_tile(index, two_columns);
        let (x, y) = battle_hud_tile_origin(tile_x, tile_y);
        let display_entry = scene_menu_display_entry(entry, two_columns);
        spawn_battle_command_bitmap_text(
            commands,
            rendered_art,
            asset_root,
            images,
            &display_entry,
            x,
            y,
            3.8,
        );
    }
}

fn battle_submenu_entry_tile(index: usize, two_columns: bool) -> (f32, f32) {
    if two_columns {
        let row = index / 2;
        let col = index % 2;
        (
            BATTLE_SUBMENU_ORIGIN_TILE_X + col as f32 * BATTLE_SUBMENU_COLUMN_SPACING_TILES,
            BATTLE_SUBMENU_ORIGIN_TILE_Y + row as f32 * BATTLE_SUBMENU_ROW_SPACING_TILES,
        )
    } else {
        (
            BATTLE_SUBMENU_ORIGIN_TILE_X,
            BATTLE_SUBMENU_ORIGIN_TILE_Y + index as f32 * BATTLE_SUBMENU_ROW_SPACING_TILES,
        )
    }
}

fn spawn_battle_main_command_menu(
    commands: &mut Commands,
    rendered_art: &mut RenderedTilesetArt,
    asset_root: &AssetRoot,
    images: &mut Assets<Image>,
    entries: &[String],
) {
    spawn_battle_window(
        commands,
        rendered_art,
        asset_root,
        images,
        BATTLE_MAIN_MENU_LEFT_TILE,
        BATTLE_MAIN_MENU_TOP_TILE,
        BATTLE_MAIN_MENU_WIDTH_TILES,
        BATTLE_MAIN_MENU_HEIGHT_TILES,
        3.5,
    );
    for (index, entry) in entries.iter().enumerate() {
        let (tile_x, tile_y) = battle_main_menu_entry_tile(index);
        let (x, y) = battle_hud_tile_origin(tile_x, tile_y);
        spawn_battle_command_bitmap_text(
            commands,
            rendered_art,
            asset_root,
            images,
            &compact_scene_label(entry, 7),
            x,
            y,
            3.8,
        );
    }
}

fn battle_command_entries_are_main_menu(entries: &[String]) -> bool {
    if entries.len() != BATTLE_MAIN_MENU_LABELS.len() {
        return false;
    }
    entries
        .iter()
        .zip(BATTLE_MAIN_MENU_LABELS)
        .all(|(entry, label)| {
            let trimmed = entry.trim_start_matches(|ch| ch == '>' || ch == ' ').trim();
            trimmed == label
        })
}

#[cfg(test)]
fn battle_main_menu_panel_center() -> (f32, f32) {
    (
        PLAYFIELD_LEFT
            + (BATTLE_MAIN_MENU_LEFT_TILE + BATTLE_MAIN_MENU_WIDTH_TILES * 0.5) * TILE_SIZE,
            BATTLE_PLAYFIELD_TOP
            - (BATTLE_MAIN_MENU_TOP_TILE + BATTLE_MAIN_MENU_HEIGHT_TILES * 0.5) * TILE_SIZE,
    )
}

fn battle_main_menu_entry_tile(index: usize) -> (f32, f32) {
    let row = index / 2;
    let col = index % 2;
    (
        BATTLE_MAIN_MENU_ORIGIN_TILE_X + col as f32 * BATTLE_MAIN_MENU_COLUMN_SPACING_TILES,
        BATTLE_MAIN_MENU_ORIGIN_TILE_Y + row as f32 * BATTLE_MAIN_MENU_ROW_SPACING_TILES,
    )
}

fn spawn_battle_move_menu(
    commands: &mut Commands,
    snapshot: &RuntimeShellSnapshot,
    runtime_shell: &BevyRuntimeShell,
    battle: &crate::RuntimeBattleSnapshot,
    rendered_art: &mut RenderedTilesetArt,
    asset_root: &AssetRoot,
    images: &mut Assets<Image>,
) {
    let Some((slot, cursor_index, visible_rows, start)) =
        battle_move_menu_state(snapshot, runtime_shell, battle)
    else {
        return;
    };
    spawn_battle_window(
        commands,
        rendered_art,
        asset_root,
        images,
        BATTLE_MOVE_SELECTION_LEFT_TILE,
        BATTLE_MOVE_SELECTION_TOP_TILE,
        BATTLE_MOVE_SELECTION_WIDTH_TILES,
        BATTLE_MOVE_SELECTION_HEIGHT_TILES,
        3.5,
    );
    let total = battle_move_menu_option_count_for_slot(slot);
    for visible_index in 0..visible_rows {
        let index = start + visible_index;
        if index >= total {
            break;
        }
        let marker = if index == cursor_index { ">" } else { " " };
        let label = if index < slot.pokemon.moves.len() {
            battle_move_display_name(snapshot, &slot.pokemon.moves[index].name)
        } else {
            "CANCEL".to_string()
        };
        let (tile_x, tile_y) = battle_move_menu_entry_tile(visible_index);
        let (x, y) = battle_hud_tile_origin(tile_x, tile_y);
        spawn_battle_command_bitmap_text(
            commands,
            rendered_art,
            asset_root,
            images,
            &compact_scene_label(&format!("{marker}{label}"), 12),
            x,
            y,
            3.8,
        );
    }
    spawn_battle_move_info_window(
        commands,
        snapshot,
        &slot.pokemon,
        cursor_index,
        rendered_art,
        asset_root,
        images,
    );
}

fn spawn_battle_window(
    commands: &mut Commands,
    rendered_art: &mut RenderedTilesetArt,
    asset_root: &AssetRoot,
    images: &mut Assets<Image>,
    tile_x: f32,
    tile_y: f32,
    width_tiles: f32,
    height_tiles: f32,
    z: f32,
) {
    let (center_x, center_y) = battle_window_center(tile_x, tile_y, width_tiles, height_tiles);
    if width_tiles > 2.0 && height_tiles > 2.0 {
        commands.spawn((
            SpriteBundle {
                sprite: Sprite {
                    color: Color::rgb(0.91, 0.96, 0.86),
                    custom_size: Some(Vec2::new(
                        TILE_SIZE * (width_tiles - 2.0),
                        TILE_SIZE * (height_tiles - 2.0),
                    )),
                    ..default()
                },
                transform: Transform::from_xyz(center_x, center_y, z),
                ..default()
            },
            BattleCommandMarker,
        ));
    }
    if let Some(frame) = battle_window_frame_art(rendered_art, asset_root, images) {
        let width = width_tiles.round().max(0.0) as usize;
        let height = height_tiles.round().max(0.0) as usize;
        if width >= 2 && height >= 2 {
            spawn_battle_window_frame_tiles(
                commands,
                frame,
                tile_x,
                tile_y,
                width,
                height,
                z + 0.05,
            );
            return;
        }
    }
}

fn spawn_battle_move_info_window(
    commands: &mut Commands,
    snapshot: &RuntimeShellSnapshot,
    pokemon: &crate::core::models::pokemon::Pokemon,
    cursor_index: usize,
    rendered_art: &mut RenderedTilesetArt,
    asset_root: &AssetRoot,
    images: &mut Assets<Image>,
) {
    spawn_battle_window(
        commands,
        rendered_art,
        asset_root,
        images,
        BATTLE_MOVE_INFO_LEFT_TILE,
        BATTLE_MOVE_INFO_TOP_TILE,
        BATTLE_MOVE_INFO_WIDTH_TILES,
        BATTLE_MOVE_INFO_HEIGHT_TILES,
        3.5,
    );
    let selected = pokemon.moves.get(cursor_index);
    if let Some(selected) = selected {
        let move_data = snapshot
            .moves
            .iter()
            .find(|move_data| move_data.move_id == selected.name);
        let move_type = move_data
            .map(|move_data| move_data.move_type.as_str())
            .unwrap_or("NONE");
        let base_pp = move_data
            .map(|move_data| move_data.pp)
            .unwrap_or(selected.current_pp);
        spawn_battle_move_info_text(
            commands,
            rendered_art,
            asset_root,
            images,
            "TYPE/",
            1.0,
            9.0,
        );
        spawn_battle_move_info_text(
            commands,
            rendered_art,
            asset_root,
            images,
            &compact_scene_label(&battle_type_display_name(move_type), 10),
            2.0,
            10.0,
        );
        spawn_battle_move_info_text(
            commands,
            rendered_art,
            asset_root,
            images,
            &format!(
                "PP {:>2}/{:>2}",
                selected.current_pp.min(99),
                base_pp.min(99)
            ),
            1.0,
            11.0,
        );
    } else {
        spawn_battle_move_info_text(
            commands,
            rendered_art,
            asset_root,
            images,
            "TYPE/",
            1.0,
            9.0,
        );
        spawn_battle_move_info_text(
            commands,
            rendered_art,
            asset_root,
            images,
            "----",
            2.0,
            10.0,
        );
        spawn_battle_move_info_text(
            commands,
            rendered_art,
            asset_root,
            images,
            "PP --/--",
            1.0,
            11.0,
        );
    }
}

fn spawn_battle_move_info_text(
    commands: &mut Commands,
    rendered_art: &mut RenderedTilesetArt,
    asset_root: &AssetRoot,
    images: &mut Assets<Image>,
    text: &str,
    tile_x: f32,
    tile_y: f32,
) {
    let (x, y) = battle_hud_tile_origin(tile_x, tile_y);
    spawn_battle_command_bitmap_text(commands, rendered_art, asset_root, images, text, x, y, 3.8);
}

fn battle_window_frame_art<'a>(
    rendered_art: &'a mut RenderedTilesetArt,
    asset_root: &AssetRoot,
    images: &mut Assets<Image>,
) -> Option<&'a WindowFrameArt> {
    if rendered_art.window_frame_cache.is_none() && rendered_art.window_frame_error.is_none() {
        match load_window_frame_art(asset_root, images) {
            Ok(frame) => rendered_art.window_frame_cache = Some(frame),
            Err(error) => rendered_art.window_frame_error = Some(error.to_string()),
        }
    }
    rendered_art.window_frame_cache.as_ref()
}

fn spawn_battle_window_frame_tiles(
    commands: &mut Commands,
    frame: &WindowFrameArt,
    tile_x: f32,
    tile_y: f32,
    width: usize,
    height: usize,
    z: f32,
) {
    let top_y = tile_y;
    let bottom_y = tile_y + height.saturating_sub(1) as f32;
    let left_x = tile_x;
    let right_x = tile_x + width.saturating_sub(1) as f32;
    spawn_battle_window_frame_tile(commands, &frame.top_left, left_x, top_y, z);
    spawn_battle_window_frame_tile(commands, &frame.top_right, right_x, top_y, z);
    spawn_battle_window_frame_tile(commands, &frame.bottom_left, left_x, bottom_y, z);
    spawn_battle_window_frame_tile(commands, &frame.bottom_right, right_x, bottom_y, z);

    for col in 1..width.saturating_sub(1) {
        let x = tile_x + col as f32;
        spawn_battle_window_frame_tile(commands, &frame.top_edge, x, top_y, z);
        spawn_battle_window_frame_tile(commands, &frame.top_edge, x, bottom_y, z);
    }
    for row in 1..height.saturating_sub(1) {
        let y = tile_y + row as f32;
        spawn_battle_window_frame_tile(commands, &frame.side_edge, left_x, y, z);
        spawn_battle_window_frame_tile(commands, &frame.side_edge, right_x, y, z);
    }
}

#[cfg(test)]
fn battle_window_frame_tile_count(width: usize, height: usize) -> usize {
    if width < 2 || height < 2 {
        return 0;
    }
    width * 2 + height.saturating_sub(2) * 2
}

