fn battle_move_menu_state<'a>(
    snapshot: &'a RuntimeShellSnapshot,
    runtime_shell: &BevyRuntimeShell,
    battle: &crate::RuntimeBattleSnapshot,
) -> Option<(&'a crate::RuntimePartySlotSnapshot, usize, usize, usize)> {
    let active_index = battle.active_player_party_index?;
    let slot = snapshot
        .party
        .slots
        .iter()
        .find(|slot| slot.index == active_index)?;
    let total = slot.pokemon.moves.len() + 1;
    let cursor_index =
        strict_readonly_cursor_index(&runtime_shell.battle_move_cursor, "battle:moves", total)?;
    let visible_rows = battle_move_visible_rows(total);
    let start = if total > visible_rows {
        cursor_index
            .saturating_sub(visible_rows - 1)
            .min(total - visible_rows)
    } else {
        0
    };
    Some((slot, cursor_index, visible_rows, start))
}

fn battle_move_menu_option_count(
    snapshot: &RuntimeShellSnapshot,
    battle: &crate::RuntimeBattleSnapshot,
) -> Option<usize> {
    let active_index = battle.active_player_party_index?;
    let slot = snapshot
        .party
        .slots
        .iter()
        .find(|slot| slot.index == active_index)?;
    Some(battle_move_menu_option_count_for_slot(slot))
}

fn battle_move_menu_option_count_for_slot(slot: &crate::RuntimePartySlotSnapshot) -> usize {
    slot.pokemon.moves.len() + 1
}

fn battle_move_visible_rows(total: usize) -> usize {
    let inner_height = BATTLE_MOVE_SELECTION_HEIGHT_TILES - 2.0;
    let rows = (inner_height / BATTLE_MOVE_MENU_ROW_SPACING_TILES)
        .floor()
        .max(1.0) as usize;
    total.min(rows)
}

fn battle_window_center(
    tile_x: f32,
    tile_y: f32,
    width_tiles: f32,
    height_tiles: f32,
) -> (f32, f32) {
    (
        PLAYFIELD_LEFT + (tile_x + width_tiles * 0.5) * TILE_SIZE,
        BATTLE_PLAYFIELD_TOP - (tile_y + height_tiles * 0.5) * TILE_SIZE,
    )
}

fn battle_move_menu_entry_tile(visible_index: usize) -> (f32, f32) {
    (
        BATTLE_MOVE_MENU_ORIGIN_TILE_X,
        BATTLE_MOVE_MENU_ORIGIN_TILE_Y + visible_index as f32 * BATTLE_MOVE_MENU_ROW_SPACING_TILES,
    )
}

fn battle_move_display_name(snapshot: &RuntimeShellSnapshot, move_id: &str) -> String {
    snapshot
        .moves
        .iter()
        .find(|move_data| move_data.move_id == move_id)
        .map(|move_data| move_data.name.clone())
        .unwrap_or_else(|| format!("INVALID MOVE {move_id}"))
}

fn battle_type_display_name(move_type: &str) -> String {
    move_type
        .strip_suffix("_TYPE")
        .unwrap_or(move_type)
        .replace('_', " ")
}

fn visible_battle_command_menu_entries(
    snapshot: &RuntimeShellSnapshot,
    runtime_shell: &BevyRuntimeShell,
    battle: &crate::RuntimeBattleSnapshot,
) -> Vec<String> {
    if let Some(mode) = runtime_shell.battle_pack_target_mode {
        return visible_battle_pack_target_entries(snapshot, runtime_shell, mode);
    }
    if runtime_shell.battle_move_cursor.is_some() {
        return visible_battle_move_entries(snapshot, runtime_shell, battle);
    }
    if runtime_shell.battle_switch_cursor.is_some() {
        return visible_battle_switch_entries(snapshot, runtime_shell, battle);
    }
    if runtime_shell.bag_cursor.is_some() {
        return visible_battle_item_entries(snapshot, runtime_shell);
    }
    if runtime_shell.ball_cursor.is_some() {
        return visible_battle_ball_entries(snapshot, runtime_shell);
    }
    if let Some(entries) = battle_outcome_prompt_entries(battle) {
        return entries;
    }
    let actions = visible_battle_action_ids(snapshot, battle);
    if actions.is_empty() {
        return Vec::new();
    }
    let selected = strict_readonly_cursor_index(
        &runtime_shell.battle_action_cursor,
        "battle:actions",
        actions.len(),
    );
    let Some(selected) = selected else {
        return vec![compact_scene_label("INVALID CURSOR battle:actions", 30)];
    };
    let selected_action = actions[selected];
    battle_main_menu_entries(battle_main_menu_index_for_action(selected_action))
}

fn battle_main_menu_entries(selected: usize) -> Vec<String> {
    BATTLE_MAIN_MENU_LABELS
        .iter()
        .enumerate()
        .map(|(index, label)| format!("{}{label}", if selected == index { ">" } else { " " }))
        .collect()
}

fn battle_main_menu_index_for_action(action: VisibleBattleAction) -> usize {
    match action {
        VisibleBattleAction::Fight => 0,
        VisibleBattleAction::Pokemon => 1,
        VisibleBattleAction::Pack => 2,
        VisibleBattleAction::Run => 3,
    }
}

fn battle_outcome_prompt_entries(battle: &crate::RuntimeBattleSnapshot) -> Option<Vec<String>> {
    if battle.enemy_pokemon.hp > 0 {
        return None;
    }
    match &battle.kind {
        crate::RuntimeBattleKind::Trainer {
            trainer_name,
            reward,
            ..
        } => {
            let Some(active_enemy) = battle.active_enemy_party_index else {
                return Some(vec![compact_scene_label(
                    &format!("{trainer_name} INVALID ENEMY"),
                    30,
                )]);
            };
            let active_rewarded = battle.rewarded_enemy_party_indices.contains(&active_enemy);
            let unresolved_enemy_count = battle
                .enemy_party
                .iter()
                .enumerate()
                .filter(|(index, _)| !battle.rewarded_enemy_party_indices.contains(index))
                .count();
            if active_rewarded && unresolved_enemy_count == 0 {
                Some(vec![
                    compact_scene_label(&format!("TRAINER {trainer_name}"), 30),
                    compact_scene_label("FINISH BATTLE", 30),
                ])
            } else if !active_rewarded && unresolved_enemy_count == 1 {
                Some(vec![
                    compact_scene_label(&format!("TRAINER {trainer_name}"), 30),
                    compact_scene_label(&format!("CLAIM ${reward}"), 30),
                ])
            } else {
                Some(vec![
                    compact_scene_label(
                        &format!("ENEMY {} FAINTED", battle.enemy_pokemon.species.id),
                        30,
                    ),
                    "NEXT POKEMON".to_string(),
                ])
            }
        }
        crate::RuntimeBattleKind::Wild { .. } | crate::RuntimeBattleKind::StaticWild { .. } => {
            Some(vec![
                compact_scene_label(
                    &format!("WILD {} FAINTED", battle.enemy_pokemon.species.id),
                    30,
                ),
                "CLAIM REWARD".to_string(),
            ])
        }
    }
}

fn visible_battle_switch_entries(
    snapshot: &RuntimeShellSnapshot,
    runtime_shell: &BevyRuntimeShell,
    battle: &crate::RuntimeBattleSnapshot,
) -> Vec<String> {
    let selected = strict_readonly_cursor_index(
        &runtime_shell.battle_switch_cursor,
        "battle:switch",
        battle.commands.switch_party_indices.len(),
    );
    let Some(selected) = selected else {
        return vec![compact_scene_label("INVALID CURSOR battle:switch", 30)];
    };
    let mut entries = if trainer_shift_switch_pending(snapshot, battle)
        && runtime_shell.pending_battle_move_switch_slot.is_none()
    {
        let Some(next_enemy) = next_unresolved_trainer_enemy_label(battle) else {
            return vec![compact_scene_label("INVALID TRAINER SHIFT", 30)];
        };
        vec![compact_scene_label(
            &format!("ENEMY SENDS {next_enemy}"),
            30,
        )]
    } else {
        Vec::new()
    };
    entries.extend(
        windowed_index_range(selected, battle.commands.switch_party_indices.len()).map(|index| {
            let party_index = battle.commands.switch_party_indices[index];
            let marker = if index == selected { ">" } else { " " };
            let Some(slot) = snapshot
                .party
                .slots
                .iter()
                .find(|slot| slot.index == party_index)
            else {
                return compact_scene_label(&format!("{marker}INVALID PARTY {party_index}"), 30);
            };
            format!(
                "{marker}{} {}/{}",
                slot.pokemon.species.id, slot.pokemon.hp, slot.pokemon.max_hp
            )
        }),
    );
    entries.into_iter().take(SCENE_MENU_VISIBLE_ROWS).collect()
}

fn next_unresolved_trainer_enemy_label(battle: &crate::RuntimeBattleSnapshot) -> Option<&str> {
    let enemy_index = battle.active_enemy_party_index?;
    battle
        .enemy_party
        .iter()
        .enumerate()
        .skip(enemy_index + 1)
        .find_map(|(_, pokemon)| (pokemon.hp > 0).then_some(pokemon.species.id.as_str()))
}

fn visible_battle_item_entries(
    snapshot: &RuntimeShellSnapshot,
    runtime_shell: &BevyRuntimeShell,
) -> Vec<String> {
    let item_ids = carried_battle_usable_item_ids(snapshot);
    let selected = strict_readonly_cursor_index(
        &runtime_shell.bag_cursor,
        "battle:bag-items",
        item_ids.len(),
    );
    let Some(selected) = selected else {
        return vec![compact_scene_label("INVALID CURSOR battle:bag-items", 30)];
    };
    let mut entries = Vec::new();
    entries.extend(windowed_index_range(selected, item_ids.len()).map(|index| {
        let item_id = &item_ids[index];
        let marker = if index == selected { ">" } else { " " };
        let Some(quantity) = carried_item_quantity(snapshot, item_id) else {
            return compact_scene_label(&format!("{marker}{item_id} INVALID INVENTORY"), 30);
        };
        compact_scene_label(
            &format!(
                "{marker}{item_id} x{quantity} {}",
                item_catalog_detail_label(snapshot, item_id)
            ),
            30,
        )
    }));
    entries.into_iter().take(SCENE_MENU_VISIBLE_ROWS).collect()
}

