        assert_eq!(
            image.texture_descriptor.size.width,
            (20 * SOURCE_TILE_SIZE) as u32
        );
        assert_eq!(
            image.texture_descriptor.size.height,
            (18 * SOURCE_TILE_SIZE) as u32
        );
        assert_eq!(
            &image.data[0..4],
            &[255, 255, 255, 255],
            "MainMenu draws over a white background, not the animated title art"
        );
