    fn single_track_midi(track: &[u8]) -> Vec<u8> {
        let mut bytes = Vec::new();
        bytes.extend_from_slice(b"MThd");
        bytes.extend_from_slice(&6u32.to_be_bytes());
        bytes.extend_from_slice(&0u16.to_be_bytes());
        bytes.extend_from_slice(&1u16.to_be_bytes());
        bytes.extend_from_slice(&96u16.to_be_bytes());
        bytes.extend_from_slice(b"MTrk");
        bytes.extend_from_slice(&(track.len() as u32).to_be_bytes());
        bytes.extend_from_slice(track);
        bytes
    }

    #[test]
    fn midi_parser_rejects_zero_tempo_meta_event() {
        let bytes = single_track_midi(&[
            0x00, 0xff, 0x51, 0x03, 0x00, 0x00, 0x00, 0x00, 0x90, 0x3c, 0x40, 0x60, 0x80, 0x3c,
            0x00, 0x00, 0xff, 0x2f, 0x00,
        ]);
        let error = parse_standard_midi(&bytes).expect_err("zero tempo must be invalid");
        assert!(
            error.to_string().contains("tempo meta event"),
            "unexpected error: {error:#}"
        );
    }

    #[test]
    fn midi_parser_rejects_unterminated_notes() {
        let bytes = single_track_midi(&[
            0x00, 0xff, 0x51, 0x03, 0x07, 0xa1, 0x20, 0x00, 0x90, 0x3c, 0x40, 0x00, 0xff, 0x2f,
            0x00,
        ]);
        let error = parse_standard_midi(&bytes).expect_err("open note must be invalid");
        assert!(
            error.to_string().contains("unterminated note"),
            "unexpected error: {error:#}"
        );
    }
